-- Rebuild ingredients and tags for every dish except Nui Noodles (fixed in 20261007060000).
-- The old auto-enrichment matched substrings: "rice" tagged dishes "iced", "steamed"/"steak"
-- added "tea", "lemongrass" added "lemon", "pineapple" added "apple", and almost every dish was
-- tagged "mild" even when spicy. Tags are rebuilt from each dish's name and description with
-- whole-word matching; halal/vegetarian/jay tags follow the dish's is_halal/is_vegetarian/is_jay.
-- Allergens: only the false ones the bad ingredients caused are removed (gluten from "toasted
-- rice powder", dairy from "cream soda" / "without milk"); "egg" is corrected to "eggs" (the
-- value user allergies match) and eggs added where the dish plainly contains egg.
update public.menu_items m set ingredients = v.ingredients, tags = v.tags, allergens = v.allergens, updated_at = now()
